// Supplied by the user, inlined as data URIs because the artifact CSP blocks
// remote images. Infisical arrives as a lockup (infinity mark + wordmark) on
// its lime ground, which turns to mush at 16px -- so it is shown zoomed and
// framed on the infinity alone via background-size/position, which keeps the
// real artwork and the exact brand colour instead of a redrawn approximation.
// LiveKit is a wordmark, so it stands in for the text label rather than
// sitting beside it.
window.LOGO_IMG = {
  infisical: "data:image/jpeg;base64,",
  livekit: "data:image/png;base64,"
};
